UPDATE t_payment_attempt
SET active_action_id = #{actionId}, version = version + 1, update_time = #{now}
WHERE payment_attempt_id = #{attempt.paymentAttemptId} AND version = #{attempt.version}
AND active_action_id IS NULL AND attempt_status = 'PROCESSING'

UPDATE t_payment_attempt
SET active_action_id =

    #{nextActionId}
    NULL

,
version = version + 1, update_time = #{now}
WHERE payment_attempt_id = #{attempt.paymentAttemptId} AND version = #{attempt.version}
AND active_action_id = #{actionId} AND attempt_status = 'PROCESSING'

UPDATE t_payment_attempt
SET attempt_status = 'FAILED', active_action_id = NULL,
version = version + 1, update_time = #{now}
WHERE payment_attempt_id = #{attempt.paymentAttemptId} AND version = #{attempt.version}
AND active_action_id = #{activeActionId} AND attempt_status = 'PROCESSING'

UPDATE t_payment_attempt
SET authorized_amount = #{authorizedAmount}, active_action_id = NULL,
version = version + 1, update_time = #{now}
WHERE payment_attempt_id = #{paymentAttemptId} AND active_action_id = #{activeActionId}
AND attempt_status = #{oldStatus} AND version = #{version}

UPDATE t_payment_attempt
SET authorized_amount = #{payAmount}, captured_amount = #{payAmount},
attempt_status = #{newStatus}, active_action_id = NULL,
version = version + 1, update_time = #{now}
WHERE payment_attempt_id = #{paymentAttemptId} AND active_action_id = #{activeActionId}
AND attempt_status = #{oldStatus} AND version = #{version}
